class Solution {
public:
 int minimumTeachings(int n,vector<vector<int>>& languages,vector<vector<int>>& friendships){
  int m=languages.size();vector<vector<char>> knows(m+1,vector<char>(n+1));
  for(int i=0;i<m;++i)for(int x:languages[i])knows[i+1][x]=1;
  unordered_set<int> affected;
  for(auto& f:friendships){int a=f[0],b=f[1];bool common=false;
   for(int x=1;x<=n;++x)if(knows[a][x]&&knows[b][x]){common=true;break;}
   if(!common){affected.insert(a);affected.insert(b);}
  }
  int ans=affected.size();for(int x=1;x<=n;++x){int need=0;for(int u:affected)if(!knows[u][x])++need;ans=min(ans,need);}
  return ans;
 }
};
